CREATE TABLE `velix_production_budgets` (`run_id` text PRIMARY KEY NOT NULL REFERENCES `velix_production_runs`(`id`) ON DELETE CASCADE, `currency` text NOT NULL DEFAULT 'USD', `limit_usd` real NOT NULL, `reserve_usd` real NOT NULL DEFAULT 0, `consumed_usd` real NOT NULL DEFAULT 0, `policy` text NOT NULL DEFAULT 'approval_required', `updated_at` text NOT NULL DEFAULT (datetime('now')))
